debug('begin add_signature: FA_SETUP4A_PRORATECALGAP');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21193',
      p_sig_id                 => 'FA_SETUP4A_PRORATECALGAP',
      p_sig_sql                => 'SELECT 
    fc.calendar_type,
    fc.start_date,
    fc.end_date
FROM
    fa_calendar_periods fc,
    fa_deprn_periods fdp,
    fa_book_controls fbc
WHERE
    fbc.prorate_calendar = fc.calendar_type
    AND fbc.book_type_code = fdp.book_type_code
    AND fbc.book_type_code = ''##$$PBook$$##''
    AND fdp.period_close_date IS NULL
    AND fc.start_date >= fdp.period_open_date
    AND NOT EXISTS (
        SELECT
            fc1.start_date
        FROM
            fa_calendar_periods fc1
        WHERE
            fc.end_date + 1 = fc1.start_date
            AND fc1.calendar_type = fc.calendar_type
    )
    AND fc.end_date <> (select max(fc2.end_date) from fa_calendar_periods fc2
