debug('begin add_signature: FA_SETUP4B_ASSETCALOVERLAP');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('##STYLE##End Date'):= ',#333333,#FFE864,bold';
   l_info('##STYLE##Overlap End Date'):= ',#333333,#FFE864,bold';
   l_info('##STYLE##Overlap Start Date'):= ',#333333,#FFE864,bold';
   l_info('##STYLE##Start Date'):= ',#333333,#FFE864,bold';
  add_signature(
      p_sig_repo_id            => '1347',
      p_sig_id                 => 'FA_SETUP4B_ASSETCALOVERLAP',
      p_sig_sql                => '-- Modified SQL for performance - 2/11/22
SELECT cp1.calendar_type  "Calendar"
,cp1.period_name  "Period"
,cp1.period_num   "Period Number"
,cp1.start_date   "Start Date"
,cp1.end_date      "End Date"
,cp2.period_name   "Overlap Period"
,cp2.period_num   "Overlap Period Number"
,cp2.start_date   "Overlap Start Date"
,cp2.end_date     "Overlap End Date"
FROM FA_CALENDAR_PERIODS cp1, FA_CALENDAR_PERIODS cp2
WHERE cp1.calendar_type= cp2.calendar_type
and cp1.period_name <>cp2.period_name
and cp1.start_date<=cp2.start_date
and cp1.end_date>cp2.start_date
and  to_char(cp1.start_date , ''YYYY'') >=  to_char(sysdate, ''YYYY'')

/* Original SQL - 2/10/22
SELECT   cp1.calendar_type  "Calendar"
,cp1.period_name  "Period"
,cp1.period_num   "Period Number"
,cp1.start_date   "Start Date"
,cp1.end_date      "End Date"
,cp2.period_name   "Overlap Period"
,cp2.period_num   "Overlap Period Number"
,cp2.start_date   "Overlap Start Date "
,cp2.end_date     "Overlap End Date"
FROM     FA_CALENDAR_PERIODS cp1, FA_CALENDAR_PERIODS cp2
WHERE    cp1.calendar_type = cp2.calendar_type 
AND      cp1.start_date >= NVL( to_date(''##$$STARTDATE$$##'', ''DD-MM-YYYY''), cp1.start_date) 
AND      cp1.end_date   <= NVL( to_date(''##$$ENDDATE$$##'', ''DD-MM-YYYY''), cp1.end_date) 
AND      cp1.period_name  <> cp2.period_name 
AND    ( cp2.start_date between cp1.start_date and cp1.end_date 
OR cp2.end_date between cp1.start_date and cp1.end_date)
*/',
      p_title                  => 'Asset Calendar Overlap Check',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found Asset Calendar date overlapping.',
      p_solution               => 'Please follow solution in [304135/KB750732] - Can the Starting and Ending Days of a Period in the FA Calendar be Changed?',
      p_success_msg            => 'No Asset Calendar date overlapping was found.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: FA_SETUP4B_ASSETCALOVERLAP');



debug('begin add_signature: FA_SETUP5_PRORATECONV3');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21240',
      p_sig_id                 => 'FA_SETUP5_PRORATECONV3',
      p_sig_sql                => 'SELECT ct.prorate_convention_code     "Prorate Convention Code"
,ct.description                 "Description"
,ct.fiscal_year_name            "Fiscal Year"
,ct.depr_when_acquired_flag     "Depr From DPIS"
,cn1.start_date                 "Defined From"
,cn2.end_date                   "Defined To"
FROM     FA_CONVENTION_TYPES ct, FA_CONVENTIONS cn1, FA_CONVENTIONS cn2
WHERE    cn1.prorate_convention_code = ct.prorate_convention_code
AND      cn2.prorate_convention_code = ct.prorate_convention_code
AND      cn1.start_date = ( SELECT   MIN(cn3.start_date)
FROM     FA_CONVENTIONS cn3
WHERE    cn3.prorate_convention_code = ct.prorate_convention_code )
AND      cn2.start_date =
( SELECT   MAX(cn3.start_date) FROM FA_CONVENTIONS cn3
WHERE cn3.prorate_convention_code = ct.prorate_convention_code)
AND ct.fiscal_year_name = (
select fiscal_year_name from  FA_BOOK_CONTROLS_SEC where book_type_code = ''##$$PBook$$##'')
order by cn1.start_date DESC',
      p_title                  => 'Prorate Conventions by Book',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No Prorate Conventions were found for this book.',
      p_solution               => 'Please follow solution (option #5) in [139937/KB558728] - Calendar Usage And Setup',
      p_success_msg            => 'Prorate Conventions defined for this book.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: FA_SETUP5_PRORATECONV3');



debug('begin add_signature: FA_SETUP5A_PRORATECONVGAPS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1349',
      p_sig_id                 => 'FA_SETUP5A_PRORATECONVGAPS',
      p_sig_sql                => '--Modified 1/11/22
SELECT 
    fc.prorate_convention_code,
    fc.start_date,
    fc.end_date
FROM
    fa_conventions fc,
    fa_deprn_periods fdp,
    fa_books fb
WHERE
    fb.transaction_header_id_out IS NULL
    AND asset_id = (
        SELECT
            fa.asset_id
        FROM
            fa_additions fa
        WHERE
            fa.asset_number = ''##$$AssetID$$##''
    )
    AND fb.prorate_convention_code = fc.prorate_convention_code
    AND fb.book_type_code = fdp.book_type_code
    AND fb.book_type_code = ''##$$PBook$$##''
    AND fdp.period_close_date IS NULL
    AND fc.start_date >= fdp.period_open_date
    AND  NOT EXISTS (
        SELECT
            fc1.start_date
        FROM
            fa_conventions fc1
        WHERE
            fc.end_date + 1 = fc1.start_date
            AND fc1.prorate_convention_code = fc.prorate_convention_code
            AND fc1.start_date>fc.end_date
           )
           AND fc.end_date <> (select max(fc2.end_date) from fa_conventions fc2
           where fc2.prorate_convention_code=fc.prorate_convention_code
           )
           order by fc.end_date desc

/* Modified code as of 8/21/20
with prorate_conv_gap_chk_book as
( select prorate_convention_code, oldest + level Missing_Start_Date
    from 
    ( 
    select c.prorate_convention_code
           , min(start_date) oldest
           , max(end_date) recent
    from FA_BOOKS b, FA_CONVENTIONS c
where b.prorate_convention_code = c.prorate_convention_code
and b.prorate_convention_code in 
        ( 
        select distinct prorate_convention_code
        from FA_BOOKS
        where DATE_INEFFECTIVE is null
        and BOOK_TYPE_CODE = ''##$$PBook$$##''
        )
and b.BOOK_TYPE_CODE = ''##$$PBook$$##''
and c.start_date between trunc(sysdate, ''YEAR'') and add_months(trunc(sysdate, ''YEAR''), 12)-1 -- check for current fiscal year
and c.start_date - c.end_date = 0 -- check for Daily Prorate Convention
group by c.prorate_convention_code
    )
 connect by level <= recent - oldest - 1
)
select prorate_convention_code, Missing_Start_Date
  from prorate_conv_gap_chk_book
 minus
select c.prorate_convention_code, c.start_date
  from FA_BOOKS b, FA_CONVENTIONS c
  where c.prorate_convention_code in 
    ( 
    select distinct prorate_convention_code
    from FA_BOOKS
    where DATE_INEFFECTIVE is null
    and BOOK_TYPE_CODE = ''##$$PBook$$##''
    )
    and b.BOOK_TYPE_CODE = ''##$$PBook$$##''
    and c.start_date between trunc(sysdate, ''YEAR'') and add_months(trunc(sysdate, ''YEAR''), 12)-1 -- check for current fiscal year
    and c.start_date - c.end_date = 0 -- check for Daily Prorate Convention
*/

/* Original code as of 8/16/20
SELECT   cn.prorate_convention_code       "Prorate Convention Code"
,cn.start_date                    "Start Date"
,cn.end_date                      "End Date"
,cn.prorate_date                  "Prorate Date"
FROM     FA_CONVENTIONS cn 
WHERE    cn.start_date >= NVL( to_date(''##$$STARTDATE$$##'', ''DD-MM-YYYY''), cn.start_date) 
AND      cn.end_date   <= NVL( to_date(''##$$ENDDATE$$##'', ''DD-MM-YYYY''), cn.end_date) 
AND      NOT EXISTS ( SELECT   cn2.start_date 
FROM     FA_CONVENTIONS cn2 
WHERE    cn2.prorate_convention_code = cn.prorate_convention_code 
AND      cn2.start_date = cn.end_date + 1 ) 
AND      cn.end_date <> ( SELECT   max(cn2.end_date) FROM FA_CONVENTIONS cn2 
WHERE    cn2.prorate_convention_code = cn.prorate_convention_code)
*/',
      p_title                  => 'Prorate Convention Date Gap Check by Book',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found date gaps in Prorate Conventions setup for this book.',
      p_solution               => 'Please follow solution in:<br>
[214398/KB742317] - How to Change an Incorrectly Defined Prorate Calendar or Convention?<br>
[139937/KB558728] - Calendar Usage And Setup (see option #5).<br><br>

Please log a Service Request, for possible datafix, referring to this internal [1968356/KB746871] - Need To Correct Date In FA Prorate Convention Calendar<br>
and provide/upload any additional information in SR.',
      p_success_msg            => 'No date gaps were found in Prorate Conventions setup for this book.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '14'
      );
   l_info.delete;
debug('end add_signature: FA_SETUP5A_PRORATECONVGAPS');



debug('begin add_signature: FA_SETUP_PRORATECONVGAPS_BY_FISCAL_YEAR');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('##STYLE##FOUND THE GAP AFTER END_DATE'):= ',#333333,#ffd6cc,bold';
  add_signature(
      p_sig_repo_id            => '21406',
      p_sig_id                 => 'FA_SETUP_PRORATECONVGAPS_BY_FISCAL_YEAR',
      p_sig_sql                => 'SELECT 
distinct fc.prorate_convention_code,
    fc.start_date,
    fc.end_date "FOUND THE GAP AFTER END_DATE"
FROM
    fa_conventions fc,
    fa_deprn_periods fdp,
    fa_books fb, 
    fa_convention_types ft
WHERE
    fb.transaction_header_id_out IS NULL
    AND fb.prorate_convention_code = fc.prorate_convention_code
    AND fb.book_type_code = fdp.book_type_code
    AND fdp.period_close_date IS NULL
    AND fc.start_date >= fdp.period_open_date
    AND ft.fiscal_year_name = (select fiscal_year_name from FA_BOOK_CONTROLS_SEC where book_type_code =''##$$PBook$$##'')
    AND  to_char(fc.start_date , ''YYYY'') >=  to_char(sysdate, ''YYYY'')
    AND  NOT EXISTS (
        SELECT
            fc1.start_date
        FROM
            fa_conventions fc1
        WHERE
            fc.end_date + 1 = fc1.start_date
            AND fc1.prorate_convention_code = fc.prorate_convention_code
            AND fc1.start_date>fc.end_date
           )
           AND fc.end_date <> (select max(fc2.end_date) from fa_conventions fc2
           where fc2.prorate_convention_code=fc.prorate_convention_code
           )
           order by fc.prorate_convention_code, fc.end_date desc',
