debug('begin add_signature: FA_SETUP6A_DEPRNMETHODSUNDEF');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1352',
      p_sig_id                 => 'FA_SETUP6A_DEPRNMETHODSUNDEF',
      p_sig_sql                => 'SELECT cb.book_type_code  "Book Type Code"
,cb.category_id        "Category Id"
,cb.deprn_method       "Deprn Method"
,cb.life_in_months     "Life In Months"
FROM      FA_CATEGORY_BOOK_DEFAULTS cb 
WHERE (   cb.deprn_method NOT IN 
( SELECT   method_code  FROM FA_METHODS ) 
OR        cb.life_in_months NOT IN 
( SELECT   life_in_months FROM FA_METHODS
WHERE    method_code = cb.deprn_method )) 
AND       cb.book_type_code IN 
( SELECT   book_type_code FROM FA_BOOK_CONTROLS_SEC ) 
ORDER BY  cb.book_type_code, cb.category_id',
      p_title                  => 'Depreciation Methods (Undefined)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found depreciation method/life combinations in FA_CATEGORY_BOOK_DEFAULTS that are not defined.',
