debug('begin add_signature: FA_SETUP6B_DEPRNMETHODSUNDEFBK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1353',
      p_sig_id                 => 'FA_SETUP6B_DEPRNMETHODSUNDEFBK',
      p_sig_sql                => 'SELECT   ad.asset_number "Asset Number"
,bk.asset_id             "Asset Id"
,bk.book_type_code       "Book Type Code"
,bk.deprn_method_code    "Deprn Method Code"
,bk.life_in_months       "Life In Months"
FROM     FA_BOOKS bk, FA_ADDITIONS ad
WHERE    bk.book_type_code = ''##$$PBook$$##''
AND      bk.date_ineffective IS NULL 
AND      bk.depreciate_flag = ''YES'' 
AND      bk.period_counter_fully_reserved IS NULL 
AND      bk.asset_id = ad.asset_id 
AND      ad.asset_type = ''CAPITALIZED'' 
AND  (   bk.deprn_method_code NOT IN 
( SELECT   method_code FROM FA_METHODS ) 
OR       bk.life_in_months NOT IN 
( SELECT   life_in_months FROM FA_METHODS 
WHERE    method_code = bk.deprn_method_code ))
AND      bk.book_type_code IN 
( SELECT   book_type_code FROM FA_BOOK_CONTROLS_SEC WHERE book_type_code = ''##$$PBook$$##'')
ORDER BY ad.asset_number',
      p_title                  => 'Depreciation Methods (Undefined) in FA_BOOKS',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found depreciation method/life combinations in FA_BOOKS that are not defined for this book.',
      p_solution               => 'The following depreciation method/life combinations in FA_BOOKS are not defined.<br><br>
ACTION - Verify and define missing depreciation method/life combinations as described in the Oracle Assets User Guide.<br>
Ensure that the Depreciation Methods combinations are setup via (N) Setup > Depreciation > Methods<br>
<a href="http://docs.oracle.com/cd/E26401_01/doc.122/e48755/T293142T302125.htm#d0e49808" target="_blank">R12.2 User Guide</a><br>
Or<br>
<a href="http://docs.oracle.com/cd/E18727_01/doc.121/e13586/T293142T302125.htm" target="_blank">R12.1 User Guide</a>',
      p_success_msg            => 'All depreciation method/life combinations in FA_BOOKS are defined for this book.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
