debug('begin add_signature: FA_SETUP7A_PRIMARYASSETBKERR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1374',
      p_sig_id                 => 'FA_SETUP7A_PRIMARYASSETBKERR',
      p_sig_sql                => 'SELECT   book_type_code          "Book Type Code"
