debug('begin add_signature: FA_SETUP7B_MINDEPRNSETUP');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1376',
      p_sig_id                 => 'FA_SETUP7B_MINDEPRNSETUP',
      p_sig_sql                => '-- Modified 1/4/22: Query display book(s) not having a minimum of 2 prerequisite periods in FA_DEPRN_PERIODS table

SELECT   dp.book_type_code "Book Type Code" ,count(*) "Periods Found"
FROM     FA_DEPRN_PERIODS dp, FA_BOOK_CONTROLS_SEC bc 
WHERE    dp.book_type_code = bc.book_type_code
AND      bc.date_ineffective IS null
GROUP BY dp.book_type_code
HAVING   count(*) < 2

/* Original sql - 1/4/22
SELECT   dp.book_type_code "Book Type Code" ,count(*) "Periods Found"
FROM     FA_DEPRN_PERIODS dp, FA_BOOK_CONTROLS_SEC bc 
WHERE    dp.book_type_code = bc.book_type_code
AND      bc.date_ineffective IS NOT null
GROUP BY dp.book_type_code
HAVING   count(*) < 2
*/',
      p_title                  => 'Minimum depreciation period setup',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found book(s) not having a minimum of 2 prerequisite periods in FA_DEPRN_PERIODS table.',
      p_solution               => 'Define the depreciation and prorate calendars for a minimum of 2 periods for associated book.<br><br>
ACTION - As a best practice, keep the calendars defined at least 1 year out for associated book.<br>
',
      p_success_msg            => 'All books have a minimum of 2 prerequisite periods in FA_DEPRN_PERIODS table.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: FA_SETUP7B_MINDEPRNSETUP');



debug('begin add_signature: FA_SETUP8_ASSETCATSETUP');
