debug('begin add_signature: FA_SETUP8B_ASSETCATASSOCBKS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1421',
      p_sig_id                 => 'FA_SETUP8B_ASSETCATASSOCBKS',
      p_sig_sql                => 'SELECT cb.category_id,
bccor.book_type_code "Corp Book",
bctax.book_type_code "Tax Book",
rtrim(nvl(ct.segment1,'' '')||''-''||nvl(ct.segment2,'' '')||''-''||
nvl(ct.segment3,'' '')||''-''||nvl(ct.segment4,'' '')||''-''||
nvl(ct.segment5,'' '')||''-''||nvl(ct.segment6,'' '')||''-''||
nvl(ct.segment7,'' ''), ''- '') Category
FROM FA_CATEGORY_BOOKS cb,
FA_CATEGORIES ct,
FA_BOOK_CONTROLS_SEC bccor,
FA_BOOK_CONTROLS_SEC bctax
WHERE UPPER(bccor.book_class) = ''CORPORATE''
AND bctax.distribution_source_book = bccor.book_type_code
AND bctax.allow_mass_copy = ''YES''
AND cb.book_type_code = bccor.book_type_code
AND ct.category_id = cb.category_id
AND bctax.date_ineffective IS NULL
AND NOT EXISTS (
SELECT cb1.book_type_code
FROM FA_CATEGORY_BOOKS cb1
WHERE cb1.category_id = cb.category_id
AND cb1.book_type_code = bctax.book_type_code )
ORDER BY bctax.book_type_code, Category, cb.category_id',
      p_title                  => 'Category setup between associated books',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found categories defined in the CORPORATE book that are not defined in the associated TAX book(s).',
      p_solution               => 'ACTION - Define missing asset categories in the associated TAX book, if required.<br>
Navigation: Setup > Asset System > Asset Categories<br>',
      p_success_msg            => 'All categories defined in the CORPORATE book and associated TAX book(s).',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: FA_SETUP8B_ASSETCATASSOCBKS');



debug('begin add_signature: FA_SETUP8C_ASSETCATASSOCBKSCIP');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1424',
      p_sig_id                 => 'FA_SETUP8C_ASSETCATASSOCBKSCIP',
      p_sig_sql                => 'SELECT   cbcor.category_id 
,bccor.book_type_code corp
,bctax.book_type_code tax
,rtrim(nvl(ct.segment1,'' '')||''-''||nvl(ct.segment2,'' '')||''-''||
         nvl(ct.segment3,'' '')||''-''||nvl(ct.segment4,'' '')||''-''||
         nvl(ct.segment5,'' '')||''-''||nvl(ct.segment6,'' '')||''-''||
         nvl(ct.segment7,'' ''), ''- '') Category
