      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: FA_SETUP8C_ASSETCATASSOCBKSCIP');



debug('begin add_signature: FA_SETUP9_BKPERIODNOTINGL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1426',
      p_sig_id                 => 'FA_SETUP9_BKPERIODNOTINGL',
      p_sig_sql                => 'SELECT   fabc.book_type_code     "Book Type Code"
,facp.calendar_type      "Calendar"
,count(*)                "Number of Periods Not In GL"
FROM     FA_BOOK_CONTROLS_SEC fabc, FA_CALENDAR_PERIODS facp, FA_DEPRN_PERIODS fadp, GL_LEDGERS glled, FA_SYSTEM_CONTROLS sys 
WHERE    facp.calendar_type = fabc.deprn_calendar 
AND      fabc.set_of_books_id = glled.ledger_id 
AND      fadp.book_type_code = fabc.book_type_code 
AND      fadp.period_counter = fabc.initial_period_counter 
AND      facp.start_date > fadp.calendar_period_open_date 
AND      facp.start_date > nvl( sys.date_placed_in_service ,fadp.calendar_period_open_date) 
AND      upper(fabc.GL_POSTING_ALLOWED_FLAG) = ''YES'' 
AND  NOT EXISTS ( SELECT  1 FROM GL_PERIODS glp 
WHERE   glp.period_set_name = glled.period_set_name 
AND     glp.period_name = facp.period_name ) 
GROUP BY fabc.book_type_code,facp.calendar_type 
ORDER BY facp.calendar_type, fabc.book_type_code',
      p_title                  => 'Asset Books (posting allowed) with Periods not defined in General Ledger',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found Periods that do not exist in General Ledger for the following asset book/calendar combinations.',
      p_solution               => 'For journal entries to be created, insure the periods are defined in General Ledger.<br>
Please refer to:<br>
[130539/KB707992] - General Ledger Calendar Setup, Usage and Troubleshooting<br>
[1316725/KB627598] - Can FA Period Names Differ from GL Period Names in R12?<br>
[2031935/KB766291] - How To Change Period Names In Fixed Assets In R12 To Be Different Than the Period Names Used In GL?',
      p_success_msg            => 'All Periods exists in General Ledger for all asset book/calendar combinations.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: FA_SETUP9_BKPERIODNOTINGL');



