      p_sig_repo_id            => '1430',
      p_sig_id                 => 'FA_SETUP12_BKCTRLPDCALSETUP',
      p_sig_sql                => 'SELECT   bc.book_type_code         "Book Type Code"
,dp1.period_name                   "Initial Period"
,dp2.period_name                   "Last Period"
,bc.last_deprn_run_date            "Last Deprn Run Date"
