debug('begin add_signature: BOOK_TYPE_CODE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15817',
      p_sig_id                 => 'BOOK_TYPE_CODE',
      p_sig_sql                => 'select DISTINCT
bk.BOOK_TYPE_CODE,
bc.DISTRIBUTION_SOURCE_BOOK,
bc.BOOK_CLASS,
TO_CHAR(bc.DATE_INEFFECTIVE,''DD-MM-YYYY HH24:MI:SS'') DATE_INEFFECTIVE,
bc.SET_OF_BOOKS_ID as Ledger_Id,
gl.SHORT_NAME as Ledger_Name,
to_char(bc.LAST_DEPRN_RUN_DATE,''DD-MM-YYYY HH24:MI:SS'') LAST_DEPRN_RUN_DATE,
bc.DEPRN_STATUS,
bc.MASS_REQUEST_ID,
bc.LAST_PERIOD_COUNTER,
dp.PERIOD_COUNTER	
from fa_books bk, fa_book_controls bc, fa_deprn_periods dp, gl_ledgers gl
                          where bc.book_type_code = bk.book_type_code
                          and dp.book_type_code = bk.book_type_code
                          and dp.period_close_date is null
                          and bk.date_ineffective is null
                          --and bk.asset_id =''##$$AssetID$$##'' --8/19/24: removed to retrieve ''Book Information''
                          and bc.distribution_source_book = ''##$$PBook$$##''
                         and gl.ledger_id = bc.SET_OF_BOOKS_ID
order by 1,3',
      p_title                  => 'Book Information',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Book information not found.',
      p_solution               => '',
      p_success_msg            => 'Book information found.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: BOOK_TYPE_CODE');



