debug('begin add_signature: 804686.1-CHILD');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9998',
      p_sig_id                 => '804686.1-CHILD',
      p_sig_sql                => 'select et.valuation_method "Asset Book",
bc.book_class ,
ev.process_status_code ,
ev.event_status_code ,
ev.event_type_code ,
ev.event_id ,
ah.gl_transfer_status_code,
ev.event_date,
th.date_effective,
dp.calendar_period_open_date,
dp.calendar_period_close_date
from xla_transaction_entities et ,
xla_events ev ,
xla_ae_headers ah ,
fa_book_controls bc ,
fa_transaction_headers th ,
fa_deprn_periods dp
where et.application_id = ##$$APPS_PARAM1$$##
and et.entity_code = ''TRANSACTIONS''
and et.source_id_int_1 = th.transaction_header_id
and ev.application_id = ##$$APPS_PARAM1$$##
and ev.entity_id = et.entity_id
and ev.event_date < dp.calendar_period_open_date
and ah.application_id(+) = ##$$APPS_PARAM1$$##
and ah.event_id(+) = ev.event_id
and bc.distribution_source_book = th.book_type_code
and et.valuation_method = bc.book_type_code
and bc.book_type_code = dp.book_type_code
and et.APPLICATION_ID  = ev.APPLICATION_ID --added 10/2/19
and ah.APPLICATION_ID  = ev.APPLICATION_ID --added 10/2/19
and ah.ENTITY_ID       = ev.ENTITY_ID --added 10/2/19
and ah.EVENT_TYPE_CODE = ev.EVENT_TYPE_CODE --added 10/2/19
and bc.BOOK_TYPE_CODE  = th.BOOK_TYPE_CODE  --added 10/2/19
and dp.BOOK_TYPE_CODE = th.BOOK_TYPE_CODE  --added 10/2/19
and th.date_effective between dp.period_open_date
and nvl(dp.period_close_date, sysdate)
and et.valuation_method = ''##$$FK1$$##''
and ah.gl_transfer_status_code <> ''Y''
and ev.process_status_code=''P''
and ev.event_status_code=''P''
order by ev.event_date, ev.event_id, ev.event_type_code',
