debug('begin add_signature: 804686.1-PARENT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9997',
      p_sig_id                 => '804686.1-PARENT',
      p_sig_sql                => 'select et.valuation_method "Asset Book",
et.valuation_method "##$$FK1$$##",
bc.book_class,
ev.process_status_code,
ev.event_status_code,
ev.event_type_code,
ah.gl_transfer_status_code,
count(*) "#Events w/Incorrect Event Date"
from xla_transaction_entities et ,
xla_events ev ,
xla_ae_headers ah ,
fa_book_controls bc ,
fa_transaction_headers th ,
fa_deprn_periods dp
where et.application_id = ##$$APPS_PARAM1$$##
and bc.book_type_code = ''##$$PBook$$##''
and et.entity_code = ''TRANSACTIONS''
and et.source_id_int_1 = th.transaction_header_id
and ev.application_id = ##$$APPS_PARAM1$$##
and ev.entity_id = et.entity_id
and ev.event_date < dp.calendar_period_open_date
and ah.application_id(+) = ##$$APPS_PARAM1$$##
and ah.event_id(+) = ev.event_id
and bc.distribution_source_book = th.book_type_code
and et.valuation_method = bc.book_type_code
and bc.book_type_code = dp.book_type_code
and et.APPLICATION_ID  = ev.APPLICATION_ID --added 10/2/19
and ah.APPLICATION_ID  = ev.APPLICATION_ID --added 10/2/19
and ah.ENTITY_ID       = ev.ENTITY_ID --added 10/2/19
and ah.EVENT_TYPE_CODE = ev.EVENT_TYPE_CODE --added 10/2/19
and bc.BOOK_TYPE_CODE  = th.BOOK_TYPE_CODE  --added 10/2/19
and dp.BOOK_TYPE_CODE = th.BOOK_TYPE_CODE  --added 10/2/19
and th.date_effective between dp.period_open_date
and nvl(dp.period_close_date, sysdate)
and ah.gl_transfer_status_code <> ''Y''
and ev.process_status_code=''P''
and ev.event_status_code=''P''
group by et.valuation_method,
bc.book_class, 
ev.process_status_code,
ev.event_status_code,
ev.event_type_code,
ah.gl_transfer_status_code',
      p_title                  => 'Events having incorrect Event Date and were not Transferred to GL',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found events, for backdated transactions, which were not transferred to GL due to incorrect event date caused by the following Bugs:<br>
Bug 6860984 - SLA: PLACEHOLDER FOR CORRECTING EVENT DATE FOR ALL ENTITIES <br>
Bug 7292561 - AFTER 6860984 BACKDATED RETIREMENTS XFR > GL BASED ON EVENT DATE VS FA PERIOD
',
      p_solution               => 'Please log a Service Request, for possible datafix, referring to this internal [804686/KB782231] - How To Datafix FA Events Having Incorrect Event Date And Were Not Transferred To GL and provide SQL output in SR.',
      p_success_msg            => 'No events were found that was not transferred to GL due to incorrect event date.
',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('804686.1-CHILD'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '14'
      );
   l_info.delete;
debug('end add_signature: 804686.1-PARENT');



debug('begin add_signature: 2502503.1_FA_TRN_HDR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13242',
      p_sig_id                 => '2502503.1_FA_TRN_HDR',
      p_sig_sql                => 'select bc.book_type_code, ev.event_id, ev.event_type_code, ev.entity_id, ev.event_date, ev.EVENT_STATUS_CODE, ev.PROCESS_STATUS_CODE
from xla_events ev, xla_transaction_entities et, fa_book_controls bc
where et.VALUATION_METHOD = bc.book_type_code
and ev.entity_id = et.entity_id
and ev.application_id = ##$$APPS_PARAM1$$##
and et.application_id = ##$$APPS_PARAM1$$##
and bc.book_type_code = ''##$$PBook$$##''
and NOT EXISTS (select 1 from fa_transaction_headers b where 
ev.event_id=b.event_id)
and ev.EVENT_STATUS_CODE not in (''N'',''P'')
and ev.event_type_code <> ''DEPRECIATION''
order by ev.event_date, ev.event_id, ev.event_type_code',
      p_title                  => 'Orphan Transaction Headers accounting events',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found these Orphan Transaction Headers accounting events which does not have any corresponding transactions on the fixed asset side. 
These accounting events will never get processed by Create Accounting program and they will continue to appear in the "Subledger Period Close Exception Report".',
      p_solution               => 'Please log a Service Request, for possible datafix, referring to this internal [2502503/KB227601] - How to Find Out the Orphan Events In Fixed Assets ?',
      p_success_msg            => 'No Orphan Transaction Headers accounting events found.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: 2502503.1_FA_TRN_HDR');



debug('begin add_signature: 2502503.1_FA_DD');
