      p_sig_sql                => 'SELECT
     event_id,
     event_type_code,
     entity_id,
     event_date,
     event_status_code,
     process_status_code
 FROM
     xla_events a
 WHERE
     application_id = ##$$APPS_PARAM1$$##
     and event_type_code=''DEPRECIATION''
