debug('begin add_signature: XLA_ACCT_CLASS_ASSGNS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1025',
      p_sig_id                 => 'XLA_ACCT_CLASS_ASSGNS',
      p_sig_sql                => 'SELECT XACA.assignment_code, XACA.accounting_class_code, XAD.ledger_id, XAD.enabled_flag 
FROM xla_acct_class_assgns XACA, xla_assignment_defns_b XAD, xla_post_acct_progs_b XPAP 
WHERE XACA.program_code = XAD.program_code 
AND XACA.program_owner_code = XAD.program_owner_code
AND XAD.program_code = XPAP.program_code 
AND XAD.program_owner_code = XPAP.program_owner_code
AND XPAP.program_code = ''Mass Additions Create''       
AND XACA.assignment_code = XAD.assignment_code 
AND XACA.assignment_owner_code = XAD.assignment_owner_code 
AND XPAP.program_owner_code = ''S''       
AND XPAP.application_id = 140 
AND XACA.accounting_class_code in (Select distinct accounting_class_code from XLA_ACCT_LINE_TYPES_B where application_id = 200)',
      p_title                  => 'Accounting Class Assignments - XLA_ACCT_CLASS_ASSGNS',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Accounting Class Assignments does not exist for assets to be transferred.',
      p_solution               => '',
      p_success_msg            => 'Only those Line types that are enabled for Mass Additions will be transferred to Assets.<br />
Example: If the results do not include accounting_class_code = ''NRTAX'', Then Non-Recoverable Taxes are not configured for transfer to Assets.<br />
<br />
ACTION - If Non-Recoverable Tax should be transferred to Fixed Assets, then it needs to be setup as follows:<br />
<br />
In Payables Responsibility, navigate to:<br />
1) Setup -> Accounting Setups -> Subledger Accounting Setup -> Post-Accounting Programs<br />
2) Query for Program Name ''Mass Additions Create''<br />
3) Go to ''Accounting Class Assignments''<br />
4) Create a new accounting class assignment for Non-Recoverable Tax',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: XLA_ACCT_CLASS_ASSGNS');



