  add_signature(
      p_sig_repo_id            => '13227',
      p_sig_id                 => 'FA_DC_INVALID_THID',
      p_sig_sql                => 'select dp.book_type_code
,dp.period_name
,ad.asset_number
,aj.asset_id
,SUBSTR(aj.source_type_code,1,20) source_type_code
,aj.transaction_header_id
 from   fa_adjustments aj
,fa_deprn_periods dp
,fa_book_controls bc
,fa_additions ad
 where  dp.period_close_date  is null
and  aj.book_type_code = dp.book_type_code
and  bc.book_type_code = dp.book_type_code
and  aj.period_counter_created = dp.period_counter
and  ad.asset_id   = aj.asset_id
and  dp.book_type_code = ''##$$PBook$$##''
and  not exists
(select ''thid exists''
 from  fa_transaction_headers th
 where th.asset_id = aj.asset_id
and th.transaction_header_id = aj.transaction_header_id
and (th.book_type_code = aj.book_type_code
OR
th.book_type_code = bc.distribution_source_book))
order by 1,2,3',
