AND dp.period_close_date is NULL
AND dp.book_type_code = ''##$$PBook$$##''
AND aj.period_counter_created = dp.period_counter 
AND aj.asset_id = dd2.asset_id
AND aj.book_type_code = dd2.book_type_code 
AND aj.period_counter_created = dd2.period_counter
ORDER BY 1,2,3',
