,mt.Depreciate_Lastyear_Flag
,rt.Year
,rt.Period_Placed_In_Service
,rt.Rate
from fa_methods mt, fa_rates rt, fa_books bk, fa_calendar_periods cp,FA_BOOK_CONTROLS fbc
 where mt.method_id = rt.method_id
