 and mt.life_in_months = bk.life_in_months
 and fbc.book_type_code=''##$$PBook$$##''
 and bk.asset_id = ''##$$AssetID$$##''
 and bk.book_type_code = ''##$$PBook$$##''
 and cp.calendar_type = fbc.PRORATE_CALENDAR
 and bk.prorate_date between cp.start_date and cp.end_date
 and rt.PERIOD_PLACED_IN_SERVICE = cp.period_num
 order by mt.method_code, mt.life_in_months, rt.year',
