      p_sig_repo_id            => '15727',
      p_sig_id                 => 'CALENDAR',
      p_sig_sql                => 'select CP.Period_Num,CP.Period_Name,TO_CHAR(cp.start_date,''DD-MM-YYYY HH24:MI:SS'') start_date,
TO_CHAR(cp.end_date,''DD-MM-YYYY HH24:MI:SS'') end_date,
ct.fiscal_year_name,ct.period_suffix_type,ct.number_per_fiscal_year,ct.description 
FROM fa_calendar_types ct,fa_fiscal_year fy,fa_calendar_periods cp,fa_book_controls fbc
where CT.calendar_type = cp.calendar_type and cp.calendar_type = fbc.DEPRN_CALENDAR
AND fy.fiscal_year_name = fbc.FISCAL_YEAR_NAME
and fbc.book_type_code=''##$$PBook$$##''
and fy.fiscal_year BETWEEN (CURRENT_FISCAL_YEAR-1) AND CURRENT_FISCAL_YEAR
and fy.fiscal_year_name = ct.fiscal_year_name and cp.start_date >= fy.start_date 
and cp.end_date <= fy.end_date
order by fy.fiscal_year desc, cp.period_num',
      p_title                  => 'Calendar',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No Calendar is present for the book.',
      p_solution               => '',
      p_success_msg            => 'Calendar is present for the book.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
