debug('begin add_signature: CONVENTIONS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15728',
      p_sig_id                 => 'CONVENTIONS',
      p_sig_sql                => 'select CT.PRORATE_CONVENTION_CODE,CT.DESCRIPTION,TO_CHAR(CO.START_DATE,''DD-MM-YYYY HH24:MI:SS'') start_date,
TO_CHAR(CO.END_DATE,''DD-MM-YYYY HH24:MI:SS'') end_date,
TO_CHAR(CO.PRORATE_DATE,''DD-MM-YYYY HH24:MI:SS'') PRORATE_DATE,CT.DEPR_WHEN_ACQUIRED_FLAG 
FROM FA_CONVENTIONS CO, FA_CONVENTION_TYPES CT, FA_FISCAL_YEAR FY ,fa_book_controls fbc
WHERE FY.FISCAL_YEAR BETWEEN (fbc.CURRENT_FISCAL_YEAR-1) AND fbc.CURRENT_FISCAL_YEAR
AND FY.FISCAL_YEAR_NAME =fbc.FISCAL_YEAR_NAME
AND (CO.PRORATE_CONVENTION_CODE IN (select distinct PRORATE_CONVENTION_CODE from fa_books
     where asset_id = ''##$$AssetID$$##''   and book_type_code = ''##$$PBook$$##'')
OR CO.PRORATE_CONVENTION_CODE in (select distinct RETIREMENT_PRORATE_CONVENTION from fa_retirements
where asset_id =''##$$AssetID$$##''   and book_type_code = ''##$$PBook$$##''))
AND CO.START_DATE BETWEEN FY.START_DATE AND FY.END_DATE
AND CO.PRORATE_CONVENTION_CODE = CT.PRORATE_CONVENTION_CODE 
ORDER BY CT.PRORATE_CONVENTION_CODE, CO.START_DATE',
