    union
    select ev.event_id
    from fa_transaction_headers th, xla_transaction_entities en, xla_events ev,fa_book_controls fbc
    where th.book_type_code =''##$$PBook$$##''
    and fbc.book_type_code=th.book_type_code
    and th.asset_id =''##$$AssetID$$##''
    and en.application_id  in (FND_GLOBAL.resp_appl_id,140)
    and en.ledger_id in (fbc.set_of_books_id,FA_XLA_EVENTS_PVT.get_secondary_sob_id(''##$$PBook$$##'') )
    and th.transaction_type_code in (''REINSTATEMENT'')
    and en.entity_code in (''TRANSACTIONS'')
    and nvl(en.source_id_int_1, (-99)) = th.transaction_header_id
    and en.valuation_method =''##$$PBook$$##''
    and en.valuation_method <>''##$$PBook$$##''
    and ev.application_id in (FND_GLOBAL.resp_appl_id,140)
    and ev.entity_id = en.entity_id
    union
    select ev.event_id
    from fa_transaction_headers th, xla_transaction_entities en, xla_events ev,fa_book_controls fbc
