    from fa_transaction_headers th, xla_transaction_entities en, xla_events ev,fa_book_controls fbc
    where th.book_type_code =''##$$PBook$$##''
    and fbc.book_type_code=th.book_type_code
    and th.asset_id =''##$$AssetID$$##''
    and en.application_id  in (FND_GLOBAL.resp_appl_id,140)
    and en.ledger_id in (fbc.set_of_books_id,FA_XLA_EVENTS_PVT.get_secondary_sob_id(''##$$PBook$$##'') )
     and en.entity_code in (''MANUAL'', ''INTER_ASSET_TRANSACTIONS'')
    and nvl(en.source_id_int_1, (-99)) = th.trx_reference_id
    and ev.application_id in (FND_GLOBAL.resp_appl_id,140)
	and NVL(en.valuation_method,'' '') = th.book_type_code
	  and ev.entity_id = en.entity_id 
	and ev.application_id = en.application_id 
    union
    select ev.event_id
    from xla_transaction_entities en, xla_events ev, fa_book_controls bc, fa_deprn_detail dd
    where bc.book_type_code =''##$$PBook$$##''
    and en.application_id  in (FND_GLOBAL.resp_appl_id,140)
    and en.ledger_id in (bc.set_of_books_id,FA_XLA_EVENTS_PVT.get_secondary_sob_id(''##$$PBook$$##'') )
     and en.entity_code in (''MANUAL'', ''DEPRECIATION'')
  and NVL(en.source_id_int_1,-99)    = dd.asset_id 
      and NVL(en.source_id_int_2,-99)    = dd.period_counter  
      and NVL(en.source_id_int_3,-99)    = dd.deprn_run_id 
      and NVL(en.valuation_method,'' '') = dd.book_type_code
    and dd.asset_id  =''##$$AssetID$$##''
    and dd.book_type_code  = ''##$$PBook$$##''
    and ev.application_id =en.application_id  
 and dd.event_id = ev.event_id
    and ev.entity_id = en.entity_id 
