      and ev.entity_id                    = en.entity_id
      and ev.application_id               = en.application_id
      and dd.event_id = ev.event_id
    and dd.asset_id  =''##$$AssetID$$##''
    and  dd.tax_book_type_code = ''##$$PBook$$##''
and dd.corp_book_type_code=bc.distribution_source_book
    and ev.application_id =en.application_id  
    and ev.entity_id = en.entity_id) )',
