debug('begin add_signature: FA_TABLESPACE_ISSUE');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('##STYLE##TableSpace Name'):= 'left,#333333,#FFE864,bold';
  add_signature(
      p_sig_repo_id            => '19522',
      p_sig_id                 => 'FA_TABLESPACE_ISSUE',
      p_sig_sql                => 'SELECT a.TABLESPACE_NAME "TableSpace Name",
           round(a.BYTES / 1024 / 1024) "MB Allocated",
           round((a.BYTES-nvl(b.BYTES, 0)) / 1024 / 1024) "MB Used",
           nvl(round(b.BYTES / 1024 / 1024), 0) "MB Free",
           round(((a.BYTES-nvl(b.BYTES, 0))/a.BYTES)*100,2) "Pct Used",
           round((1-((a.BYTES-nvl(b.BYTES,0))/a.BYTES))*100,2) "Pct Free"
    FROM   (select   TABLESPACE_NAME,
                     sum(BYTES) BYTES
            from     sys.dba_data_files
            group by TABLESPACE_NAME) a,
           (select   TABLESPACE_NAME,
                     sum(BYTES) BYTES
            from     sys.dba_free_space
            group by TABLESPACE_NAME) b
  WHERE  a.TABLESPACE_NAME = b.TABLESPACE_NAME (+)
  AND (round((1-((a.BYTES-nvl(b.BYTES,0))/a.BYTES))*100,2) < 3)
  order  by ((a.BYTES-b.BYTES)/a.BYTES) desc',
      p_title                  => 'Potential Tablespace Issue',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The objects listed above have 3% or less tablespace free and will create performance issues.',
      p_solution               => '<p>Review items indicated and add additional data files to the tablespace as required.</p>
<p><a href="https://docs.oracle.com/en/database/oracle/oracle-database/21/admin/managing-tablespaces.html">Guidelines for Managing Tablespaces</a></p>',
      p_success_msg            => 'No potential tablespace issues detected.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: FA_TABLESPACE_ISSUE');



