debug('begin add_signature: FA_GATHER_STATS_RUN');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '19523',
      p_sig_id                 => 'FA_GATHER_STATS_RUN',
      p_sig_sql                => 'SELECT Decode(substr(UPPER(ARGUMENT_TEXT),1,3),''FA'', ''FA'', ''GL,'', ''GL'',''XDO'',''XDO'', substr(UPPER(ARGUMENT_TEXT),1,3)) "Schema",
ACTUAL_COMPLETION_DATE "Completion Date",
ARGUMENT_TEXT
	FROM
FND_CONCURRENT_PROGRAMS_TL PT,
FND_CONCURRENT_PROGRAMS PB,
FND_CONCURRENT_REQUESTS R,
FND_LOOKUP_VALUES STAT,
FND_LOOKUP_VALUES PHAS
	WHERE PB.APPLICATION_ID = R.PROGRAM_APPLICATION_ID AND PB.CONCURRENT_PROGRAM_ID = R.CONCURRENT_PROGRAM_ID
	AND PB.APPLICATION_ID = PT.APPLICATION_ID AND PB.CONCURRENT_PROGRAM_ID = PT.CONCURRENT_PROGRAM_ID
	AND PT.LANGUAGE = ''US'' and
	STAT.LOOKUP_CODE = R.STATUS_CODE AND STAT.LOOKUP_TYPE = ''CP_STATUS_CODE'' AND PHAS.LOOKUP_CODE = R.PHASE_CODE
	AND PHAS.LOOKUP_TYPE = ''CP_PHASE_CODE'' and PHAS.language=''US'' and STAT.language=''US'' and PHAS.VIEW_APPLICATION_ID = 0 and STAT.VIEW_APPLICATION_ID = 0
	AND UPPER(USER_CONCURRENT_PROGRAM_NAME) LIKE ''GATHER SCHEMA%''
	AND substr(UPPER(ARGUMENT_TEXT),1,3) in (''ALL'',''GL,'', ''FA'',''XDO'' )
	and PHAS.MEANING=''Completed'' and STAT.MEANING=''Normal'' and ACTUAL_COMPLETION_DATE > sysdate-30
order by ACTUAL_COMPLETION_DATE desc',
      p_title                  => 'Gather Schema Statistics',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Gather schema statistics was not run for  Fixed Assets, Subledger or General Ledger Schema in last 30 days.',
      p_solution               => 'In order to schedule the program, use [419728/KB627293] Concurrent Processing - How To Gather Statistics On Oracle Applications Release 11i and/or Release 12 - Concurrent Process, Temp Tables, Manually. 
This warning can be ignored if gather stats was run using command Prompt.',
      p_success_msg            => 'Gather statistics was run in last 30 days. No Stale Stats exists.
',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: FA_GATHER_STATS_RUN');



debug('begin add_signature: EBS_FIN_FA_INSTANCE_OVERVIEW');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '31654',
      p_sig_id                 => 'EBS_FIN_FA_INSTANCE_OVERVIEW',
      p_sig_sql                => 'select ''Instance Name = ''|| instance_name  ||  ''   ''||  upper(sys_context(''USERENV'',''DB_NAME''))  "Instance Summary" from v$instance
union
select ''Host Name = ''|| host_name from v$instance
union
select ''Applications = ''|| release_name from fnd_product_groups
union
select ''Instance Creation Date = '' || created from v$database
union
select ''Database = '' || banner db_version from v$version where rownum = 1
union
SELECT distinct ''Forms Server = '' || extractValue(XMLType(TEXT),''//forms_version[@oa_var="s_forms_version"]'') FROM fnd_oam_context_files WHERE name NOT IN (''TEMPLATE'',''METADATA'') AND (status IS NULL OR status !=''H'') AND CTX_TYPE IN (''A'')and rownum=1
union
select ''Platform = '' || SUBSTR(REPLACE(REPLACE(pcv1.product, ''TNS for ''), '':'' )||pcv2.status, 1, 80)
FROM product_component_version pcv1,product_component_version pcv2 WHERE UPPER(pcv1.product) LIKE ''%TNS%'' AND UPPER(pcv2.product) LIKE ''%ORACLE%'' AND ROWNUM = 1
union
select ''Language = '' || VALUE FROM V$NLS_PARAMETERS WHERE parameter = ''NLS_LANGUAGE''
union
select ''Character Set = '' || VALUE FROM V$NLS_PARAMETERS WHERE parameter = ''NLS_CHARACTERSET''
union
SELECT ''Product status: Oracle Assets (OFA) is '' || L.MEANING
FROM fnd_application b, fnd_application_tl t, FND_PRODUCT_INSTALLATIONS I, fnd_lookup_values L
WHERE (b.APPLICATION_ID = I.APPLICATION_ID)
AND b.application_id = t.application_id
AND (b.APPLICATION_ID = ''140'')
AND (L.LOOKUP_TYPE = ''FND_PRODUCT_STATUS'')
AND (L.LOOKUP_CODE = I.Status)
AND t.language = ''US'' AND l.language = ''US''
union
SELECT ''Product status: Oracle Property Manager (PN) is '' || L.MEANING
FROM fnd_application b, fnd_application_tl t, FND_PRODUCT_INSTALLATIONS I, fnd_lookup_values L
WHERE (b.APPLICATION_ID = I.APPLICATION_ID)
AND b.application_id = t.application_id
AND (b.APPLICATION_ID = ''240'')
AND (L.LOOKUP_TYPE = ''FND_PRODUCT_STATUS'')
AND (L.LOOKUP_CODE = I.Status)
AND t.language = ''US'' AND l.language = ''US''
union
SELECT ''Multi Org = '' || MULTI_ORG_FLAG FROM FND_PRODUCT_GROUPS
union
SELECT ''Multi Currency = '' || MULTI_CURRENCY_FLAG FROM FND_PRODUCT_GROUPS',
      p_title                  => 'Instance Summary',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Instance details.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
