debug('begin add_signature: FA_APPSCHECK_PROFILE_VALUES');
   l_info('##MASK##USER'):= 'NO_MASK';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7207',
      p_sig_id                 => 'FA_APPSCHECK_PROFILE_VALUES',
      p_sig_sql                => 'Select fpon.profile_option_name "Profile Option Name"
,site_pov.profile_option_value "Site"
, appl_pov.profile_option_value "Application"
,resp_pov.profile_option_value "Responsibility"
,user_pov.profile_option_value "User" 
from fnd_profile_options fpon, fnd_profile_option_values user_pov
        , fnd_profile_option_values resp_pov, fnd_profile_option_values appl_pov
        , fnd_profile_option_values site_pov
        where fpon.profile_option_id = user_pov.profile_option_id(+)
        and fpon.application_id = user_pov.application_id(+)
        and fpon.profile_option_id = resp_pov.profile_option_id(+)
        and fpon.application_id = resp_pov.application_id(+)
        and fpon.profile_option_id = appl_pov.profile_option_id(+)
        and fpon.application_id = appl_pov.application_id(+)
        and fpon.profile_option_id = site_pov.profile_option_id(+)
        and fpon.application_id = site_pov.application_id(+)
        and fpon.application_id like ##$$FK3$$##
        and resp_pov.LEVEL_VALUE(+) = FND_GLOBAL.RESP_ID
        and user_pov.LEVEL_VALUE(+) = FND_GLOBAL.USER_ID
        and site_pov.level_id(+) = 10001
        and appl_pov.level_id(+) = 10002
        and resp_pov.level_id(+) = 10003
        and user_pov.level_id(+) = 10004
        and fpon.start_date_active  <= sysdate
        and nvl(fpon.end_date_active, sysdate) >= sysdate
ORDER BY fpon.profile_option_name

/* ORIGINAL SQL:
SELECT user_profile_option_name "Profile Option",
             a.profile_option_value "Profile Value",
             DECODE(a.level_id, 10001, ''Site'',
                                10002, ''Application'',
                                10003, ''Responsibility'',
                                10004, ''User'') "Level",								
             DECODE(a.level_id, 10001, ''Site'', 10002, b.application_short_name, 10003,
c.responsibility_name, 10004, rpad(
substr(d.user_name, 1, ceil(length(d.user_name)*0.25) ),
length(d.user_name), ''*''
)) "Level Value",
             c.responsibility_id
      FROM fnd_profile_option_values a,
           fnd_application b,
           fnd_responsibility_tl c,
           fnd_user d,
           fnd_profile_options e,
           fnd_profile_options_tl t
      WHERE e.application_id like ##$$FK3$$##
        AND a.profile_option_id  = e.profile_option_id
        AND a.level_value          = b.application_id(+)
        AND a.level_value          = c.responsibility_id(+)
        AND a.level_value          = d.user_id(+)
        AND t.profile_option_name  = e.profile_option_name
        AND t.LANGUAGE             = ''US''
        AND nvl(c.LANGUAGE,''US'') = ''US''
     ORDER BY e.profile_option_name
*/',
      p_title                  => 'Profile Values',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Profile Values',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: FA_APPSCHECK_PROFILE_VALUES');



