   l_info('Doc ID'):= '1339693.1';
  add_signature(
      p_sig_repo_id            => '3479',
      p_sig_id                 => '1339693.1',
      p_sig_sql                => 'SELECT Adf.Filename, Adfv.Version
    FROM Ad_Files Adf, Ad_File_Versions Adfv
    Where  
    Adf.File_Id = Adfv.File_Id
     and  
    ((''12.1'' = substr(''##$$REL$$##'',1,4) AND
            Fnd_Irep_Loader_Private.Compare_Versions(
              Adfv.Version,''120.14.12010000.19'') = ''<'' )
              Or
           (''12.0'' = substr(''##$$REL$$##'',1,4) AND
            Fnd_Irep_Loader_Private.Compare_Versions(
              Adfv.Version,''120.12.12000000.21'') = ''<'' ))
    And Adf.App_Short_Name = ''OFA''
    And Adf.Filename = ''FAMADCB.pls''
    And Adfv.Version in (
    select  "Current Version" from (
          select  afv1.version "Current Version", rank()over(partition by af1.filename order by afv1.version_segment1 desc, 
                           afv1.version_segment2 desc, afv1.version_segment3 desc, afv1.version_segment4 desc, afv1.version_segment5 desc, afv1.version_segment6 desc, afv1.version_segment7 desc,
                             afv1.version_segment8 desc, afv1.version_segment9 desc, afv1.version_segment10 desc, afv1.translation_level desc) as rankUS
            from ad_files af1, ad_file_versions afv1
          where af1.file_id = afv1.file_id
          and af1.filename in (''FAMADCB.pls'') 
          ) 
          where rankUS = 1
     )',
      p_title                  => 'Exchange Rate Variance (ERV) Line Distribution Type Not Included In Asset Cost',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Old version of code level for Mass Additions Create (package  FAMADCB.pls) does not have code fix.',
      p_solution               => 'Please follow solution in [1339693/KB795936] - R12 to R12.1 Exchange Rate Variance (ERV) Line Distribution Type Not Included In Asset Cost',
