debug('begin add_signature: 1909977.1');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '1909977.1';
  add_signature(
      p_sig_repo_id            => '2367',
      p_sig_id                 => '1909977.1',
      p_sig_sql                => 'select a.BOOK_TYPE_CODE, a.mass_addition_id, a.POSTING_STATUS, c.employee_number, h.effective_start_date, h.effective_end_date, g.actual_termination_date
from fa_mass_additions a, fa_massadd_distributions b, per_all_people_f c, fnd_user f, per_periods_of_service g, PER_ALL_ASSIGNMENTS_F h
where a.MASS_ADDITION_ID = b.MASS_ADDITION_ID
and b.employee_id = c.person_id
and b.employee_id = g.person_id
and b.employee_id = f.employee_id
and a.BOOK_TYPE_CODE = ''##$$PBook$$##''
and b.employee_id is not null
and a.POSTING_STATUS NOT IN (''POSTED'',''DELETE'',''SPLIT'')
AND h.ASSIGNMENT_TYPE IN (''E'',''A'')
AND c.PERSON_ID = h.PERSON_ID
AND g.period_of_service_id(+) = h.period_of_service_id
AND g.person_id(+)            = h.person_id
AND TRUNC(sysdate) between c.EFFECTIVE_START_DATE and c.EFFECTIVE_END_DATE
AND (
           (Trunc(sysdate) between h.EFFECTIVE_START_DATE and h.EFFECTIVE_END_DATE)
            OR
           (g.ACTUAL_TERMINATION_DATE between TRUNC(sysdate,''YEAR'') and Trunc(sysdate))
            )
and g.actual_termination_date is not null
order by c.employee_number, g.actual_termination_date, a.mass_addition_id',
      p_title                  => 'Invalid Employee assigned to Mass Addition ID',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'AP/PO has interfaced mass addition records with an employee name / employee number assigned but that employee is end-dated or terminated.<br><br>
This can cause Mass Addition Post to fail with this error in log file:<br><br>
ERROR<br>
-----------------------<br>
APP-OFA-48317: The employee to which this distribution line is assigned is no longer valid',
      p_solution               => 'Please follow solution in [1909977/KB856643] - R12.1 FAMAPT: Mass Additions Post Errors With "The Employee To Which This Distribution Line Is Assigned Is No Longer Valid"',
      p_success_msg            => 'No end-dated or terminated employees were found assigned to a mass addition id.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '15'
      );
   l_info.delete;
debug('end add_signature: 1909977.1');



