Or
(''12.0'' = substr(''##$$REL$$##'',1,4) AND
Fnd_Irep_Loader_Private.Compare_Versions(
Adfv.Version,''120.8.12000000.11'') = ''<'' ))
And Adf.App_Short_Name = ''OFA''
And Adf.Filename = ''FAPDELB.pls''
And Adfv.Version in (
    select  "Current Version" from (
          select  afv1.version "Current Version", rank()over(partition by af1.filename order by afv1.version_segment1 desc, 
                           afv1.version_segment2 desc, afv1.version_segment3 desc, afv1.version_segment4 desc, afv1.version_segment5 desc, afv1.version_segment6 desc, afv1.version_segment7 desc,
                             afv1.version_segment8 desc, afv1.version_segment9 desc, afv1.version_segment10 desc, afv1.translation_level desc) as rankUS
            from ad_files af1, ad_file_versions afv1
          where af1.file_id = afv1.file_id
          and af1.filename in (''FAPDELB.pls'') 
          ) 
          where rankUS = 1
     )',
