debug('begin add_signature: 1935201.1-Type 1');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('Doc ID'):= '1935201.1';
  add_signature(
      p_sig_repo_id            => '2915',
      p_sig_id                 => '1935201.1-Type 1',
      p_sig_sql                => 'select xah.*
from xla_ae_headers xah
where xah.application_id = 140
and xah.accounting_entry_status_code <> ''F''
and xah.gl_transfer_status_code = ''N''
and xah.balance_type_code = ''A''
and xah.parent_ae_header_id is null
and exists
(select 1
from xla_ae_headers xah1
where xah1.application_id =140
and xah1.event_id = xah.event_id
and xah1.entity_id = xah.entity_id
and xah1.balance_type_code = xah.balance_type_code
and xah1.accounting_entry_status_code = ''F''
)
and exists
(select 1
from xla_events xe
where xe.application_id =140
and xe.event_id = xah.event_id
and xe.event_status_code = ''P''
and xe.process_status_code = ''P'')',
      p_title                  => 'SLA Multiple Headers exists for same event',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'In recent times we have seen issues/errors reported multiple times for same corruption in accounting:<br><br>
