      p_success_msg            => 'Have code fix level for table definition missing [2887790/KB757935] - Table Definition Missing from Fixed Asset Analyzer and Log shows Error: ORA-00904: "UNREVALUED_COST": invalid identifier',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
