EXCEPTION WHEN others THEN
  g_retcode := 2;
  g_errbuf := 'Error in main at step '||l_step||': '||sqlerrm;
  print_log(g_errbuf);

END main;


PROCEDURE main_cp(
            errbuf                         OUT VARCHAR2
           ,retcode                        OUT VARCHAR2
           ,p_posting_book                 IN VARCHAR2    DEFAULT NULL
           ,p_asset_id                     IN NUMBER      DEFAULT NULL
           ,p_apinvoice_id                 IN NUMBER      DEFAULT NULL
           ,p_start_date                   IN VARCHAR2    DEFAULT NULL
           ,p_end_date                     IN VARCHAR2    DEFAULT NULL
           ,p_max_output_rows              IN NUMBER      DEFAULT 50
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y'
)
 IS

BEGIN
  g_retcode := 0;
  g_errbuf := null;

   main(
     p_posting_book                 => upper(p_posting_book)
    ,p_asset_id                     => p_asset_id
    ,p_apinvoice_id                 => p_apinvoice_id
    ,p_start_date                   => FND_DATE.canonical_to_date(p_start_date)
    ,p_end_date                     => FND_DATE.canonical_to_date(p_end_date)
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  retcode := g_retcode;
  errbuf  := g_errbuf;
EXCEPTION WHEN OTHERS THEN
  retcode := '2';
  errbuf := 'Error in main_cp: '||sqlerrm||' : '||g_errbuf;
END main_cp;


END fa_analyzer_pkg;
/
show errors
exit;
